// Summarise what Odoo returned so the answer is readable at a glance
// instead of buried in raw JSON.
const refunds  = $('Sample Refunds').all().map(i => i.json);
const invoices = $('Sample Invoices').all().map(i => i.json);
const product  = $('Sample Product').all().map(i => i.json)[0] || {};

// Does product.template.product_brand_id exist? dashboard_products.brand is
// currently hardcoded to null by the products sync, so every brand breakdown
// in the dashboard would silently render empty. The Brand Probe node is set to
// continue on error, so an unknown field name lands here as an error payload
// rather than killing the run.
let brandRow = {};
try { brandRow = $('Brand Probe').all().map(i => i.json)[0] || {}; } catch (e) { brandRow = { error: String(e) }; }
const brandWorks = Object.prototype.hasOwnProperty.call(brandRow, 'product_brand_id');
const productFields = Object.keys(product).sort();

const fields = Object.keys(refunds[0] || invoices[0] || {}).sort();
const want = ['move_id','invoice_user_id','commercial_partner_id','payment_state',
              'quantity','price_subtotal','price_total','invoice_date','product_id'];

const present = {};
for (const f of want) present[f] = fields.includes(f);

const sign = rows => {
  if (!rows.length) return 'NO ROWS FOUND';
  const q = rows.map(r => Number(r.quantity));
  const p = rows.map(r => Number(r.price_subtotal));
  return { quantity: q, price_subtotal: p,
           all_qty_negative: q.every(v => v < 0),
           all_subtotal_negative: p.every(v => v < 0) };
};

const rs = sign(refunds);
return [{ json: {
  field_count: fields.length,
  all_fields: fields,
  expected_fields_present: present,
  refund_signs:  rs,
  invoice_signs: sign(invoices),
  product_fields: productFields,
  brand_probe_raw: brandRow,
  BRAND_VERDICT: brandWorks
    ? ('product.template.product_brand_id EXISTS - value: ' + JSON.stringify(brandRow.product_brand_id))
    : 'product_brand_id NOT readable - brand must be dropped from the design or sourced elsewhere',
  VERDICT: refunds.length
    ? (rs.all_qty_negative
        ? 'Credit notes ARE negative - the sync can sum directly.'
        : 'WARNING: credit notes are NOT negative - the sync MUST negate out_refund rows.')
    : 'No posted credit notes found - sign behaviour unverified.'
} }];
